export interface LineBreakdown {
  lineNum: number;
  codeSnippet: string;
  constructType: 'Header / Include' | 'Function Signature' | 'Variable & Initializer' | 'Loop Construct' | 'Condition & Branch' | 'Return / Cleanup';
  title: string;
  explanation: string;
  keyDetails: {
    variableOrConstruct: string;
    role: string;
    whyThisWay: string;
  }[];
}

export interface LearnApproach {
  id: number; // 1 to 10
  name: string;
  category: string;
  description: string;
  prosCons: string;
  timeComplexity: string;
  spaceComplexity: string;
  isFree: boolean; // true for approaches 1 & 2; false for 3..10 (payable)
  code: string; // Unique solution code for this specific mental model
  lineBreakdown: LineBreakdown[]; // Unique line-by-line breakdown for this specific mental model!
}

export interface LearnModule {
  id: string;
  title: string;
  shortDesc: string;
  traceKey: string;
  difficulty: 'easy' | 'medium' | 'hard';
  category: string;
  problemStatement: {
    title: string;
    objective: string;
    description: string;
    inputDesc: string;
    outputDesc: string;
    takeaways: string[];
    examples: Array<{
      id: number;
      input: string;
      output: string;
      explanation?: string;
    }>;
    constraints: string[];
    companies: string[];
    acceptanceRate: string;
    totalAccepted: string;
  };
  approaches: LearnApproach[];
  fullCode: string;
}

