        code: `// 41. Class Templates - Approach 10: Nested Inner Node
#include <iostream>
using namespace std;

template <typename T>
class SimpleList {
private:
    struct Node {
        T data;
        Node* next;
        Node(T d) : data(d), next(nullptr) {}
    };
    Node* head;
public:
    SimpleList() : head(nullptr) {}
    ~SimpleList() {
        while (head) { Node* temp = head; head = head->next; delete temp; }
    }
    void add(T val) {
        Node* n = new Node(val);
        n->next = head;
        head = n;
    }
    T getHeadData() const { return head ? head->data : T(); }
};

int main() {
    SimpleList<int> list;
    list.add(77);
    cout << "Head data: " << list.getHeadData() << endl;
    return 0;
}`,
