        code: `// 48. Linked List - Approach 3: Delete by Value
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int d) : data(d), next(nullptr) {}
};

void pushFront(Node*& head, int val) {
    Node* n = new Node(val);
    n->next = head;
    head = n;
}

bool deleteNode(Node*& head, int val) {
    if (!head) return false;
    if (head->data == val) {
        Node* temp = head;
        head = head->next;
        delete temp;
        return true;
    }
    Node* prev = head;
    while (prev->next && prev->next->data != val)
        prev = prev->next;
    if (!prev->next) return false;
    Node* target = prev->next;
    prev->next = target->next;
    delete target;
    return true;
}

void printList(Node* h) {
    while (h) { cout << h->data << " -> "; h = h->next; }
    cout << "NULL" << endl;
}

int main() {
    Node* head = nullptr;
    for (int v : {50, 40, 30, 20, 10}) pushFront(head, v);
    printList(head);
    deleteNode(head, 30);
    cout << "After deleting 30: "; printList(head);
    deleteNode(head, 10);
    cout << "After deleting 10: "; printList(head);
    return 0;
}`,
